3	namespace App\Console\Commands;
4	
5	use App\Domain\User\UserAggregateRoot;
6	use App\Models\User;
7	use Illuminate\Console\Command;
8	use Illuminate\Support\Facades\Log;
9	
10	/**
11	 * Restore previously expired points (gettoni) to users (maintenance / correction).
12	 * Re-credits the amount and annotates the expired_points history as restored.
13	 */
14	class RestoreExpiredPoints extends Command
15	{
16	    /**
17	     * @var string
18	     */
19	    protected $signature = 'app:restore-expired-points
20	        {user? : ID di un singolo utente (per test spot); se omesso vengono processati tutti}
21	        {--date= : Ripristina solo le scadenze di questa data (Y-m-d); se omesso, tutte le scadenze non ancora ripristinate}
22	        {--reason=Ripristino punti scaduti : Motivo del ripristino}
23	        {--dry-run : Mostra cosa verrebbe ripristinato senza registrare eventi}';
24	
25	    /**
26	     * @var string
27	     */
28	    protected $description = 'Ripristina i punti scaduti agli utenti (correzione/manutenzione)';
29	
30	    public function handle(): int
31	    {
32	        $restoredAt = now('Europe/Rome')->toDateTimeString();
33	        $dryRun = (bool) $this->option('dry-run');
34	        $userId = $this->argument('user');
35	        $date = $this->option('date');
36	        $reason = (string) $this->option('reason');
37	
38	        $usersAffected = 0;
39	        $pointsRestored = 0;
40	
41	        User::query()
42	            ->when($userId, fn ($q) => $q->whereKey($userId))
43	            ->whereHas('stats', fn ($q) => $q->whereNotNull('expired_points'))
44	            ->with('stats')
45	            ->chunkById(200, function ($users) use (&$usersAffected, &$pointsRestored, $dryRun, $date, $reason, $restoredAt) {
46	                foreach ($users as $user) {
47	                    // select the non-restored entries, optionally filtered by date
48	                    $entries = $this->entriesToRestore($user->stats->expired_points ?? [], $date);
49	
50	                    if (empty($entries)) {
51	                        continue;
52	                    }
53	
54	                    $amount = (int) array_sum(array_column($entries, 'amount'));
55	
56	                    $usersAffected++;
57	                    $pointsRestored += $amount;
58	
59	                    if ($dryRun) {
60	                        continue;
61	                    }
62	
63	                    // record the restore through the aggregate: the UserProjector
64	                    // is the only place that mutates the UserStat balance.
65	                    UserAggregateRoot::retrieve($user->uuid)
66	                        ->restoreExpiredPoints($entries, $reason, $restoredAt)
67	                        ->persist();
68	                }
69	            });
70	
71	        $message = ($dryRun ? '[DRY-RUN] ' : '')
72	            .'Ripristino punti scaduti'.($date ? " del {$date}" : '').": {$usersAffected} utenti, {$pointsRestored} punti ripristinati.";
73	
74	        $this->info($message);
75	
76	        Log::info('Expired points restore', [
77	            'restored_at' => $restoredAt,
78	            'dry_run' => $dryRun,
79	            'user_id' => $userId,
80	            'date' => $date,
81	            'reason' => $reason,
82	            'users' => $usersAffected,
83	            'points' => $pointsRestored,
84	        ]);
85	
86	        return Command::SUCCESS;
87	    }
88	
89	
90	    /**
91	     * Pick the expiry entries eligible for restore: those not yet restored,
92	     * optionally filtered by a specific expiry date.
93	     * @param array<int,array<string,mixed>> $history
94	     * @param string|null $date
95	     * @return array<int,array{date:string,amount:int}>
96	     */
97	    private function entriesToRestore(array $history, ?string $date): array
98	    {
99	        $entries = [];
100	
101	        foreach ($history as $entry) {
102	            // skip entries already restored
103	            if (!empty($entry['restored_at'])) {
104	                continue;
105	            }
106	
107	            // optional filter by expiry date
108	            if ($date && $entry['date'] !== $date) {
109	                continue;
110	            }
111	
112	            $entries[] = [
113	                'date' => $entry['date'],
114	                'amount' => (int) $entry['amount'],
115	            ];
116	        }
117	
118	        return $entries;
119	    }
120	}
