3	namespace App\Domain\AwardRedeem;
4	
5	use App\Domain\AwardRedeem\Events\AwardRedeemApproved;
6	use App\Domain\AwardRedeem\Events\AwardRedeemCreated;
7	use App\Domain\AwardRedeem\Events\AwardRedeemRejected;
8	use App\Domain\AwardRedeem\Events\PointsDeducted;
9	use App\Domain\AwardRedeem\Events\PointsRestored;
10	use App\Domain\AwardRedeem\Exceptions\AwardRedeemCannotBeModified;
11	use App\Domain\AwardRedeem\Exceptions\UserCannotRequestAwardWithoutEnoughPoints;
12	use App\Enums\AwardRedeemStatus;
13	use App\Models\Award;
14	use App\Models\User;
15	use Spatie\EventSourcing\AggregateRoots\AggregateRoot;
16	
17	/**
18	 * This aggregate is used to manage the request for an award
19	 */
20	class AwardRedeemAggregateRoot extends AggregateRoot
21	{
22	    /**
23	     * User that requested the award
24	     */
25	    public string $userUuid;
26	
27	    /**
28	     * Current status of the request
29	     */
30	    protected AwardRedeemStatus $status = AwardRedeemStatus::PENDING;
31	
32	    /**
33	     * Award that is requested
34	     */
35	    public ?Award $award = null;
36	
37	    /**
38	     * Reason provided at the time of rejecting
39	     */
40	    protected ?string $rejectReason = null;
41	
42	    /**
43	     * Flag to check if the request is locked
44	     * (i.e., it cannot be modified anymore because it has been approved or rejected)
45	     */
46	    protected bool $locked = false;
47	
48	
49	    /**
50	     * Points related to the award redeem request.
51	     */
52	    public int $awardRedeemPoints = 0;
53	
54	    /**
55	     * Whether a request has already been created on this aggregate.
56	     * Used to make the submit idempotent and absorb double-submits: a fresh
57	     * aggregate has no award applied yet, a replayed one (same uuid) does.
58	     */
59	    public function isAlreadyCreated(): bool
60	    {
61	        return $this->award !== null;
62	    }
63	
64	
65	    /**
66	     * Create request for an award.
67	     * Users since 2025/08/25 can request the same award multiple times.
68	     * @param array<string,mixed> $requestPayload data that was provided by the user at the time of request
69	     */
70	    public function createRequest(
71	        Award $award,
72	        User $user,
73	        array $requestPayload
74	    ): static {
75	
76	        // check if user has enough points to redeem the award
77	        if ($user->stats->available_points < $award->redeem_points) {
78	            throw new UserCannotRequestAwardWithoutEnoughPoints(
79	                $user->id,
80	                $award->id
81	            );
82	        }
83	
84	        $createdEvent = new AwardRedeemCreated(
85	            $award->id,
86	            $user->uuid,
87	            $award->redeem_points,
88	            $requestPayload,
89	        );
90	        $this->recordThat($createdEvent);
91	
92	        $this->recordThat(
93	            (new PointsDeducted(
94	                $user->uuid,
95	                $award->redeem_points
96	            ))
97	            ->sourceEvent($createdEvent)
98	        );
99	
100	
101	        return $this;
102	    }
103	
104	
105	    /**
106	     *
107	     */
108	    public function applyAwardRedeemCreated(AwardRedeemCreated $event): void
109	    {
110	        $this->userUuid = $event->userUuid;
111	
112	        $this->award = Award::find($event->awardId);
113	
114	        $this->status = AwardRedeemStatus::PENDING;
115	
116	        $this->locked = false;
117	
118	        $this->awardRedeemPoints = $event->price;
119	
120	        // If the award is not found, throw an exception
121	        if (!$this->award) {
122	            throw new \Exception("Award with ID {$event->awardId} not found.");
123	        }
124	    }
125	
126	
127	    /**
128	     * Reject a request
129	     */
130	    public function reject(?string $reason, ?int $authUserId = null): static
131	    {
132	        $this->checkLock();
133	
134	        $rejectedEvent = new AwardRedeemRejected($reason, $authUserId);
135	
136	        $this->recordThat($rejectedEvent);
137	
138	        $this->recordThat(
139	            new PointsRestored(
140	                $this->userUuid,
141	                $this->awardRedeemPoints
142	            )
143	        );
144	
145	        return $this;
146	
147	    }
148	
149	
150	    public function applyAwardRedeemRejected(AwardRedeemRejected $event): void
151	    {
152	        $this->status = AwardRedeemStatus::REJECTED;
153	
154	        $this->rejectReason = $event->reason;
155	
156	        $this->locked = true;
157	    }
158	
159	
160	    /**
161	     * Approve a request
162	     * @param int|null $authUserId ID of the user that is approving the request
163	     */
164	    public function approve(?int $authUserId = null): static
165	    {
166	        $this->checkLock();
167	
168	        $this->recordThat(new AwardRedeemApproved($authUserId));
169	
170	
171	
172	        return $this;
173	
174	    }
175	
176	    public function applyAwardRedeemApproved(AwardRedeemApproved $event): void
177	    {
178	        $this->status = AwardRedeemStatus::APPROVED;
179	
180	        $this->locked = true;
181	
182	    }
183	
184	    /**
185	     * Check if the request is locked before change status
186	     * @throws \Exception
187	     */
188	    protected function checkLock(): void
189	    {
190	        if ($this->locked) {
191	            throw new AwardRedeemCannotBeModified($this->uuid());
192	        }
193	    }
194	
195	
196	}
