}


/**
 * Points have been deducted from a user
 * WHEN A USER REDEEMS AN AWARD.
 * This event is dispatched by AwardRedeemAggregateRoot
 * and is used to update the user with the new available points.
 * It is used when a user makes an award redeem request.
 * It is binded to the uuid of an award redeem request.
 */
public function onPointsDeducted(\App\Domain\AwardRedeem\Events\PointsDeducted $event): void
{
    /**
     * User must already exists in local system
     */
    $user = User::findUuid($event->userUuid);

    /**
     * Create a users stats if it does not exist
     */
    if (!$user->stats) {
        $user->stats()->create();
    }

    /**
     * This should never happen, but just in case
     * we check if the user has enough points
     */
    if ($user->stats->available_points < $event->pointsAmount) {
        throw new \Exception("User [{$user->uuid}]does not have enough points to complete this request [{$event->aggregateRootUuid()}]");
    }

    /**
     * Update the user with the new available points
     */
    $user->stats()->decrement('available_points', $event->pointsAmount);
    $user->stats()->increment('redemeed_points', $event->pointsAmount);

}


/**
 * Points have been restored to a user after a request has been rejected.
 */
public function onPointsRestored(\App\Domain\AwardRedeem\Events\PointsRestored $event): void
{
    /**
     * User must already exists in local system
     */
