/**
 * Points have been mnually added to a user.
 * This event is dispatched by UserAggregateRoot
 */
public function onPointsAdded(PointsAdded $event): void
{
    /**
     * User must already exists in local system
     */
    $user = User::findUuid($event->aggregateRootUuid());

    /**
     * Create a users stats if it does not exist
     */
    if (!$user->stats) {
        $user->stats()->create();
