14	/**
15	 * This projector is used to manage the request for an award
16	 */
17	class AwardRedeemProjector extends Projector
18	{
19	    /**
20	     * Here you can specify which event should trigger which method.
21	     * @var array<string,string>
22	     */
23	    protected array $handlesEvents = [
24	        AwardRedeemCreated::class => 'onAwardRedeemCreated',
25	    ];
26	
27	    /**
28	     * User attributes that are used to create the award redeem
29	     * and user must fill them in the request form.
30	     * @var array<int,string>
31	     */
32	    protected array $userAttributes = [
33	        'firstname',
34	        'lastname',
35	        'postcode',
36	        'city',
37	        'address',
38	        'address_number',
39	        'province',
40	        'phone',
41	    ];
42	
43	    /**
44	     * An award has been requested.
45	     * Create a relation record with the user and the award
46	     */
47	    public function onAwardRedeemCreated(AwardRedeemCreated $event): void
48	    {
49	
50	        // retrieve the user
51	        $user = User::findUuid($event->userUuid);
52	
53	        // retrieve the award
54	        $award = Award::find($event->awardId);
55	
56	        // build user data from payload
57	        $userData = [];
58	        foreach ($this->userAttributes as $attribute) {
59	            $userData['user_'.$attribute] = $event->requestPayload[$attribute];
60	        }
61	
62	        // add additional user data from user model
63	        $userData['user_email'] = $user->email;
64	        $userData['user_country'] = $user->country;
65	
66	
67	        // create an award redeem
68	        AwardRedeem::create(array_merge([
69	            'user_id' => $user->id,
70	            'uuid' => $event->aggregateRootUuid(),
71	            'award_id' => $award->id,
72	            'award_name' => $award->name,
73	            'award_redeem_points' => $award->redeem_points,
74	            'requested_at' => now(),
75	        ], $userData));
76	    }
77	
78	
79	    /**
80	     * A request has been rejected
81	     */
82	    public function onAwardRedeemRejected(AwardRedeemRejected $event): void
83	    {
84	
85	        // retrieve the award redeem
86	        $awardRedeem = AwardRedeem::findUuid($event->aggregateRootUuid());
87	
88	        $this->checkLock($awardRedeem);
89	
90	        // update the award redeem
91	        $awardRedeem->update([
92	            'status' => \App\Enums\AwardRedeemStatus::REJECTED,
93	            'reject_reason' => $event->reason,
94	            'rejected_at' => now(),
95	        ]);
96	    }
97	
98	
99	    /**
100	     * A request has been approved
101	     */
102	    public function onAwardRedeemApproved(AwardRedeemApproved $event): void
103	    {
104	
105	        // retrieve the award redeem
106	        $awardRedeem = AwardRedeem::findUuid($event->aggregateRootUuid());
107	
108	        $this->checkLock($awardRedeem);
109	
110	        // update the award redeem
111	        $awardRedeem->update([
112	            'status' => \App\Enums\AwardRedeemStatus::APPROVED,
113	            'approved_at' => now(),
114	        ]);
115	    }
116	
117	    /**
118	     * Check if request is pending before approving
119	     * @throws AwardRedeemCannotBeModified
120	     */
121	    public function checkLock(AwardRedeem $awardRedeem): void
122	    {
123	        // check if request is pending
124	        if ($awardRedeem->status !== \App\Enums\AwardRedeemStatus::PENDING) {
125	            throw new AwardRedeemCannotBeModified($awardRedeem->uuid);
126	        }
127	    }
128	
129	}
