public function onAwardRedeemCreated(AwardRedeemCreated $event): void
{
    /**
     * User must already exists in local system
     */
    $user = User::findUuid($event->userUuid);

    /**
     * Create a users stats if it does not exist
     */
    if (!$user->stats) {
        $user->stats()->create();
    }

    /**
     * Update the user with the new available points
     */
    $user->stats()->increment('requested_awards_count', 1);

}


/**
 * A request for award has been approved.
 */
public function onAwardRedeemApproved(AwardRedeemApproved $event): void
{
    /**
     * Get the user through the award redeem request uuid
     */
    $awardRedeem = AwardRedeem::findUuid($event->aggregateRootUuid());
    $user = $awardRedeem->user;


    /**
     * Create a users stats if it does not exist
     */
    if (!$user->stats) {
        $user->stats()->create();
    }

    /**
     * Update the user with the new available points
     */
    $user->stats()->increment('approved_awards_count', 1);
}

/**
 * A request for award has been rejected.
 */
public function onAwardRedeemRejected(AwardRedeemRejected $event): void
{
    /**
     * Get the user through the award redeem request uuid
     */
    $awardRedeem = AwardRedeem::findUuid($event->aggregateRootUuid());
    $user = $awardRedeem->user;

    /**
     * Create a users stats if it does not exist
     */
    if (!$user->stats) {
        $user->stats()->create();
    }

    /**
     * Update the user with the new available points
     */
    $user->stats()->increment('rejected_awards_count', 1);
}

