    /**
     * Check if the request is locked before change status
     * @throws \Exception
     */
    protected function checkLock(): void
    {
        if ($this->locked) {
            throw new AwardRedeemCannotBeModified($this->uuid());
        }
    }


    /**
     * Admin correction for a request that was approved by mistake: brings it
     * back to "pending" (no points involved, they stay deducted since request
     * creation) or to "rejected" (points are restored, like a normal reject).
     * Unlike reject()/approve(), this intentionally bypasses the pending-only
     * lock, since it exists specifically to fix a request that is no longer pending.
     */
    public function correctStatus(AwardRedeemStatus $newStatus, string $note, ?int $authUserId = null): static
    {
        if ($this->status !== AwardRedeemStatus::APPROVED) {
            throw new AwardRedeemCorrectionNotAllowed(
                "Only an approved request can be corrected, current status is [{$this->status->value}] for uuid [{$this->uuid()}]."
            );
        }

        if (!in_array($newStatus, [AwardRedeemStatus::PENDING, AwardRedeemStatus::REJECTED], true)) {
            throw new AwardRedeemCorrectionNotAllowed(
                "A request can only be corrected back to \"pending\" or \"rejected\", [{$newStatus->value}] given."
            );
        }

        if (trim($note) === '') {
            throw new AwardRedeemCorrectionNotAllowed('A note is required to correct the status of a request.');
        }

        $correctedEvent = new AwardRedeemStatusCorrected($this->status->value, $newStatus->value, $note, $authUserId);
        $this->recordThat($correctedEvent);

        // restore the points only when the correction cancels the award, mirroring reject()
        if ($newStatus === AwardRedeemStatus::REJECTED) {
            $this->recordThat(
                (new PointsRestored($this->userUuid, $this->awardRedeemPoints))
                    ->sourceEvent($correctedEvent)
            );
        }

        return $this;
    }


    public function applyAwardRedeemStatusCorrected(AwardRedeemStatusCorrected $event): void
    {
        $this->status = AwardRedeemStatus::from($event->newStatus);

        $this->locked = $this->status !== AwardRedeemStatus::PENDING;
    }


}

