/**
 * A request status has been corrected by an admin (it was approved by mistake).
 * Keep the approved/rejected counters in sync with the corrected status.
 */
public function onAwardRedeemStatusCorrected(AwardRedeemStatusCorrected $event): void
{
    /**
     * Get the user through the award redeem request uuid
     */
    $awardRedeem = AwardRedeem::findUuid($event->aggregateRootUuid());
    $user = $awardRedeem->user;

    /**
     * Create a users stats if it does not exist
     */
    if (!$user->stats) {
        $user->stats()->create();
    }

    // the request is no longer approved
    $user->stats()->decrement('approved_awards_count', 1);

    if ($event->newStatus === AwardRedeemStatus::REJECTED->value) {
        $user->stats()->increment('rejected_awards_count', 1);
    }
}

