class EditAwardRedeem extends EditRecord
{
    use CustomInputPage;

    protected static string $resource = AwardRedeemResource::class;

    public function getTitle(): string
    {
        return 'Dettaglio';
    }

    /**
     * Admin correction for a request that was marked as "evasa" by mistake:
     * brings it back to "pending" or "cancellato" (with automatic points
     * restore in this second case). Only available on approved requests,
     * since that is the only status this correction is meant to fix.
     */
    protected function getHeaderActions(): array
    {
        return [
            Action::make('correctStatus')
                ->label('Correggi stato')
                ->color('warning')
                ->icon('heroicon-o-arrow-uturn-left')
                ->visible(fn (AwardRedeem $record) => $record->status === AwardRedeemStatus::APPROVED)
                ->form([
                    ToggleButtons::make('status')
                        ->label('Nuovo stato')
                        ->options([
                            AwardRedeemStatus::PENDING->value => AwardRedeemStatus::PENDING->getLabel(),
                            AwardRedeemStatus::REJECTED->value => AwardRedeemStatus::REJECTED->getLabel(),
                        ])
                        ->helperText('Se riportata a "Cancellato" i punti spesi vengono riaccreditati automaticamente all\'utente.')
                        ->inline()
                        ->required(),
                    Textarea::make('note')
                        ->label('Motivo della correzione')
                        ->required()
                        ->rows(3),
                ])
                ->requiresConfirmation()
                ->action(function (array $data, AwardRedeem $record) {
                    self::correctStatus($record, $data['status'], $data['note']);

                    $this->redirect(static::getResource()::getUrl('edit', ['record' => $record]));
                }),
        ];
    }

    /**
     * @param array<string,mixed> $formData
     */
    public static function correctStatus(AwardRedeem $record, string $newStatus, string $note): void
    {
        AwardRedeemAggregateRoot::retrieve($record->uuid)
            ->correctStatus(AwardRedeemStatus::from($newStatus), $note, Auth::user()->id)
            ->persist();
    }

