    public function test_approved_request_status_can_be_corrected_to_pending(): void
    {
        [$user, $award, $formData] = $this->factory();

        $newUuid = Str::uuid();
        $aggregateRoot = AwardRedeemAggregateRoot::retrieve($newUuid)
            ->createRequest($award, $user, $formData)
            ->persist();

        $pointsAfterRequest = $user->stats->fresh()->available_points;

        AwardRedeemAggregateRoot::retrieve($newUuid)->approve()->persist();

        $aggregateRoot = AwardRedeemAggregateRoot::retrieve($newUuid)
            ->correctStatus(AwardRedeemStatus::PENDING, 'Evasa per errore', authUserId: 99);
        $aggregateRoot->persist();

        $awardRedeem = AwardRedeem::where('uuid', $newUuid)->first();

        $this->assertEquals(AwardRedeemStatus::PENDING, $awardRedeem->status);
        $this->assertNull($awardRedeem->approved_at);
        $this->assertEquals('Evasa per errore', $awardRedeem->correction_note);
        $this->assertTrue($awardRedeem->status_corrected_at->isToday());
        $this->assertEquals(99, $awardRedeem->status_corrected_by);

        // no points event should have been recorded: points stay deducted since
        // request creation and are untouched by approve()/pending
        $this->assertDatabaseMissing('stored_events', [
            'event_class' => \App\Domain\AwardRedeem\Events\PointsRestored::class,
            'aggregate_uuid' => $newUuid,
        ]);
        $this->assertEquals(
            $pointsAfterRequest,
            $user->stats->fresh()->available_points
        );

        // counters: no longer approved, still not rejected
        $this->assertEquals(0, $user->stats->fresh()->approved_awards_count);
        $this->assertEquals(0, $user->stats->fresh()->rejected_awards_count);

        // the request is pending again, so it can go through the normal flow
        AwardRedeemAggregateRoot::retrieve($newUuid)->reject('Test reason')->persist();
        $this->assertEquals(
            AwardRedeemStatus::REJECTED,
            $awardRedeem->fresh()->status
        );
    }


    public function test_approved_request_status_can_be_corrected_to_rejected(): void
    {
        [$user, $award, $formData] = $this->factory();

        $newUuid = Str::uuid();
        AwardRedeemAggregateRoot::retrieve($newUuid)
            ->createRequest($award, $user, $formData)
            ->persist();

        $pointsAfterRequest = $user->stats->fresh()->available_points;

        AwardRedeemAggregateRoot::retrieve($newUuid)->approve()->persist();

        AwardRedeemAggregateRoot::retrieve($newUuid)
            ->correctStatus(AwardRedeemStatus::REJECTED, 'Evasa per errore, premio non disponibile', authUserId: 99)
            ->persist();

        $awardRedeem = AwardRedeem::where('uuid', $newUuid)->first();

        $this->assertEquals(AwardRedeemStatus::REJECTED, $awardRedeem->status);
        $this->assertNull($awardRedeem->approved_at);
        $this->assertTrue($awardRedeem->rejected_at->isToday());
        $this->assertEquals('Evasa per errore, premio non disponibile', $awardRedeem->reject_reason);
        $this->assertEquals('Evasa per errore, premio non disponibile', $awardRedeem->correction_note);

        // points must be restored, exactly like a normal reject
        $this->assertDatabaseHas('stored_events', [
            'event_class' => \App\Domain\AwardRedeem\Events\PointsRestored::class,
            'aggregate_uuid' => $newUuid,
        ]);
        $this->assertEquals(
            $pointsAfterRequest + $award->redeem_points,
            $user->stats->fresh()->available_points
        );

        // counters: no longer approved, now rejected
        $this->assertEquals(0, $user->stats->fresh()->approved_awards_count);
        $this->assertEquals(1, $user->stats->fresh()->rejected_awards_count);
    }


    public function test_status_correction_is_only_allowed_from_approved(): void
    {
        [$user, $award, $formData] = $this->factory();

        $newUuid = Str::uuid();
        $aggregateRoot = AwardRedeemAggregateRoot::retrieve($newUuid)
