1	<?php
2	
3	namespace Spatie\EventSourcing\Console;
4	
5	use Exception;
6	use Illuminate\Console\Command;
7	use Illuminate\Support\Collection;
8	use Spatie\EventSourcing\EventHandlers\Projectors\Projector;
9	use Spatie\EventSourcing\Projectionist;
10	use Spatie\EventSourcing\StoredEvents\Repositories\StoredEventRepository;
11	
12	class ReplayCommand extends Command
13	{
14	    protected $signature = 'event-sourcing:replay {projector?*}
15	                            {--from=0 : Replay events starting from this event number}
16	                            {--stored-event-model= : Replay events from this store}
17	                            {--aggregate-uuid= : Replay events for this aggregate only}
18	                            {--force : Replay events without asking for confirmation}';
19	
20	    protected $description = 'Replay stored events';
21	
22	    protected ?Projectionist $projectionist;
23	
24	    public function handle(Projectionist $projectionist): void
25	    {
26	        $this->projectionist = $projectionist;
27	
28	        $projectors = $this->selectProjectors($this->argument('projector'));
29	
30	        if (is_null($projectors)) {
31	            $this->warn('No events replayed!');
32	
33	            return;
34	        }
35	
36	        if ($model = $this->option('stored-event-model')) {
37	            if (! class_exists($model)) {
38	                throw new Exception("Model {$model} not found. Make sure the model namespace is correct.");
39	            }
40	
41	            config(['event-sourcing.stored_event_model' => $model]);
42	        }
43	
44	        $this->replay($projectors, (int)$this->option('from'), $this->option('aggregate-uuid'));
45	    }
46	
47	    public function selectProjectors(array $projectorClassNames): ?Collection
48	    {
49	        if (count($projectorClassNames) === 0) {
50	            if (! $this->option('force') && ! $this->confirm('Are you sure you want to replay events to all projectors?', true)) {
51	                return null;
52	            }
53	
54	            return $this->projectionist->getProjectors();
55	        }
56	
57	        return collect($projectorClassNames)
58	            ->map(fn (string $projectorName) => ltrim($projectorName, '\\'))
59	            ->map(function (string $projectorName) {
60	                if (! $projector = $this->projectionist->getProjector($projectorName)) {
61	                    throw new Exception("Projector {$projectorName} not found. Did you register it?");
62	                }
63	
64	                return $projector;
65	            });
66	    }
67	
68	    public function replay(Collection $projectors, int $startingFrom, ?string $aggregateUuid = null): void
69	    {
70	        $repository = app(StoredEventRepository::class);
71	        $events = collect($projectors->toArray())->map(fn (Projector $projector) => $projector->getEventHandlingMethods()->keys())->flatten()->toArray();
72	        $replayCount = $repository->countAllStartingFrom($startingFrom, $aggregateUuid, $events);
73	
74	        if ($replayCount === 0) {
75	            $this->warn('There are no events to replay');
76	
77	            return;
78	        }
79	
80	        $this->comment("Replaying {$replayCount} events...");
81	
